private static RandomGenerator rng;
private HypergeometricDistribution dist;

@Rule
public ExpectedException expectedEx = ExpectedException.none();

@BeforeClass
public static void setUp() {
    rng = new Well19937c();
}

@Before
public void setup() {
    dist = new HypergeometricDistribution(rng, 10, 5, 2);
}

@Test
public void testConstructorWithValidParameters() {
    assertThat(dist.getPopulationSize(), is(10));
    assertThat(dist.getNumberOfSuccesses(), is(5));
    assertThat(dist.getSampleSize(), is(2));
}

@Test
public void testConstructorWithInvalidParameters() {
    expectedEx.expect(NotPositiveException.class);
    dist = new HypergeometricDistribution(rng, 0, 5, 2);

    expectedEx.expect(NotStrictlyPositiveException.class);
    dist = new HypergeometricDistribution(rng, -1, 5, 2);
    dist = new HypergeometricDistribution(rng, 10, 0, 2);
    dist = new HypergeometricDistribution(rng, 10, 5, 0);

    expectedEx.expect(NumberIsTooLargeException.class);
    dist = new HypergeometricDistribution(rng, 10, 11, 2);
    dist = new HypergeometricDistribution(rng, 10, 5, 11);
}

@Test
public void testGetNumericalMean() {
    assertThat(dist.getNumericalMean(), is(2.5));
}

@Test
public void testCumulativeProbability() {
    // Test with valid parameters
    assertThat(dist.cumulativeProbability(0), is(0.0));
    assertThat(dist.cumulativeProbability(1), is(0.0394875));
