            new double[]{2.0/3.0, 0.0, 0.0},
            new RungeKuttaStepInterpolator(new DummyStepInterpolator(), 0.0, Double.POSITIVE_INFINITY),
            1e-14, 1e14, new double[]{1e-14, 1e-14}, new double[]{1e-14, 1e-14});
    eventsManager = mock(CombinedEventsManager.class);
    stepHandler = mock(StepHandler.class);
}

@Test
public void testIntegrate() throws DerivativeException, IntegratorException {
    double[] y0 = new double[]{1.0, 2.0};
    double t0 = 0.0;
    double t = 5.0;
    double[] y = new double[y0.length];
    double result = integrator.integrate(equations, t0, y0, t, y);
    verify(equations).computeDerivatives(eq(t0), eq(y0), anyDoubleArray());
    verifyNoMoreInteractions(equations);
    assertThat(result, equalTo(5.0));
}

