public void testIntegrateWithEvents() throws DerivativeException, IntegratorException {
    when(equations.computeDerivatives(anyDouble(), anyArray(), anyDoubleArray())).thenReturn(new double[]{1.0, 2.0});
    doAnswer(invocation -> {
        StepHandler handler = invocation.getArgument(2);
        handler.handleStep((AbstractStepInterpolator) invocation.getArgument(0), false);
        return null;
    }).when(eventsManager).evaluateStep((AbstractStepInterpolator) any(), eq(false));
    when(equations.computeDerivatives(eq(3.0), anyArray(), anyDoubleArray())).thenReturn(new double[]{1.5, 2.5});
    doAnswer(invocation -> {
        StepHandler handler = invocation.getArgument(2);
        handler.handleStep((AbstractStepInterpolator) invocation.getArgument(0), true);
        return null;
    }).when(eventsManager).evaluateStep((AbstractStepInterpolator) any(), eq(true));
    double[] y0 = new double[]{1.0, 2.0};
    double t0 = 0.0;
    double t = 5.0;
    double[] y = new double[y0.length];
    integrator.setEventsManager(eventsManager);
    integrator.addEndTimeChecker(t0, t, eventsManager);
    integrator.addStepHandler(stepHandler);
    integrator.integrate(equations, t0, y0, t, y);
    verify(equations).computeDerivatives(eq(0.0), eq(y0), anyDoubleArray());
    verify(eventsManager).evaluateStep((AbstractStepInterpolator) eq(integrator.getInterpolator()), eq(false));
    verify(equations).computeDerivatives(eq(3.0), anyArray(), anyDoubleArray());
    verify(eventsManager).evaluateStep((AbstractStepInterpolator) eq(integrator.getInterpolator()), eq(true));
    verifyNoMoreInteractions(equations);

