    private List<Pair<Integer, Double>> samples;
    private DiscreteDistribution distribution;

    @Rule
    public ExpectedException expectedEx = ExpectedException.none();

    @BeforeClass
    public static void setup() {
        // Set up a random number generator for the tests
        rng = new Well19937c(System.currentTimeMillis());
    }

    @Before
    public void setUp() throws Exception {
        samples = new ArrayList<>();
        samples.add(new Pair<>(1, 0.2));
        samples.add(new Pair<>(2, 0.3));
        samples.add(new Pair<>(3, 0.4));
        samples.add(new Pair<>(4, 0.1));
        distribution = new DiscreteDistribution(rng, samples);
    }

    @Test
    public void testSample() {
        for (int i = 0; i < 100; i++) {
            final int sample = distribution.sample();
            Assert.assertTrue("Sample must be one of the defined values", samples.contains(new Pair<>(sample, 0)));
        }
    }

    @Test
    public void testProbability() {
        assertThat(distribution.probability(1), closeTo(0.2, 0.001));
        assertThat(distribution.probability(2), closeTo(0.3, 0.001));
        assertThat(distribution.probability(3), closeTo(0.4, 0.001));
        assertThat(distribution.probability(4), closeTo(0.1, 0.001));
    }

    @Test
    public void testGetSamples() {
        final List<Pair<Integer, Double>> expected = samples;
        final List<Pair<Integer, Double>> actual = distribution.getSamples();
        Assert.assertEquals(expected, actual);
    }

    @Test
    public void testSampleSize() throws NotStrictlyPositiveException {
        final int sampleSize = 2;
        final Object[] samples = distribution.sample(sampleSize);
        Assert.assertArrayEquals(new Integer[]{distribution.sample(), distribution.sample()}, samples);
    }

    @Test
    public void testNegativeProbability() {
        expectedEx.expect(NotPositiveException.class);
        expectedEx.expectMessage("The probability must be positive.");
        final List<Pair<Integer, Double>> negativeSamples = new ArrayList<>();
        negativeSamples.add(new Pair<>(1, -0.2));
        distribution = new DiscreteDistribution(rng, negativeSamples);
    }

    @Test
    public void testZeroProbability() {
        expectedEx.expect(MathIllegalArgumentException.class);
        expectedEx.expectMessage("The sum of probabilities must be strictly greater than zero.");
        final List<Pair<Integer, Double>> zeroSamples = new ArrayList<>();
        zeroSamples.add(new Pair<>(1, 0));
        distribution = new DiscreteDistribution(rng, zeroSamples);
    }

    @Test
    public void testReSeed() {
        final long seed = System.currentTimeMillis();
        distribution.reseedRandomGenerator(seed);
        verify(rng).reseed(seed);
    }
